script:
// csrd: al cambiar Entry Type o agregar fila, copia voucher_type a
// mode_of_payment de las lineas si existe un Mode of Payment con el mismo nombre.

function set_mode_of_payment_on_rows(frm, rows) {
	const entry_type = frm.doc.voucher_type;
	if (!entry_type || !rows.length) {
		return;
	}

	frappe.db.exists("Mode of Payment", entry_type).then((exists) => {
		if (!exists) {
			return;
		}

		rows.forEach((row) => {
			frappe.model.set_value(row.doctype, row.name, "mode_of_payment", entry_type);
		});
	});
}

frappe.ui.form.on("Journal Entry", {
	voucher_type(frm) {
		set_mode_of_payment_on_rows(frm, frm.doc.accounts || []);
	},

	accounts_add(frm, cdt, cdn) {
		const row = frappe.get_doc(cdt, cdn);
		set_mode_of_payment_on_rows(frm, [row]);
	},
});

// csrd: gobierna el monto del modo de pago "Efectivo" segun el
// tipo_de_factura. Reacciona en tipo_de_factura, en refresh_outside_amounts
// (que el app dispara al cambiar items) y en validate como red de seguridad.
//
//   Clientes Privados  -> Efectivo = grand_total - otros pagos (pendiente)
//   Proveedores        -> Efectivo = 0 (no se carga el monto pendiente)
//   resto              -> sin tocar (lo gobierna el app)

frappe.ui.form.on("Sales Invoice", {
    tipo_de_factura(frm) { aplicar(frm); },
    refresh_outside_amounts(frm) { aplicar(frm); },
    validate(frm) { aplicar(frm); },
});

function aplicar(frm) {
    if (frm.doc.tipo_de_factura === "Clientes Privados") {
        set_efectivo(frm, calcular_pendiente(frm));
    } else if (frm.doc.tipo_de_factura === "Proveedores") {
        set_efectivo(frm, 0);
    }
}

function calcular_pendiente(frm) {
    const otros = (frm.doc.payments || [])
        .filter(p => p.mode_of_payment !== "Efectivo")
        .reduce((s, p) => s + flt(p.amount || 0), 0);
    return flt(frm.doc.grand_total) - otros;
}

function set_efectivo(frm, monto) {
    let row = (frm.doc.payments || []).find(p => p.mode_of_payment === "Efectivo");
    if (!row) {
        row = frm.add_child("payments", { mode_of_payment: "Efectivo" });
    }
    if (flt(row.amount) !== flt(monto)) {
        frappe.model.set_value(row.doctype, row.name, "amount", monto);
    }
}
